PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?p ?class WHERE {
  ?p a ?class .
  FILTER(contains(str(?class), "Electric") || contains(str(?class), "Energy") || contains(str(?class), "Power"))
}

